type TestDatabaseClient = {
  close: () => any;
  execute: (sql: string) => Promise<any>;
};

/**
 * Shape of a single row returned by the sqlite_master introspection query used
 * by {@link resetTestDatabaseClient}.
 */
type SchemaObjectRow = {
  type: string;
  name: string;
};

// Every libsql client created while IS_TESTING is set is tracked here. libsql's
// shared in-memory database (`file::memory:?cache=shared`) only frees its
// contents once the last connection to it is closed, so leaking a client from a
// prior module instance would let its schema and data bleed into the next one.
const testDatabaseClients = new Set<TestDatabaseClient>();

/**
 * Register a database client so that {@link closeTestDatabaseClients} can later
 * close it. Called from getDb() when IS_TESTING is set.
 */
export function registerTestDatabaseClient(client: TestDatabaseClient): void {
  testDatabaseClients.add(client);
}

/**
 * Close every registered test database client and clear the registry.
 *
 * After this resolves the global registry is empty, and once the module cache
 * is reset a fresh import of the database module produces a fully isolated
 * database instance with none of the schema or data from prior instances.
 */
export async function closeTestDatabaseClients(): Promise<void> {
  const clients = Array.from(testDatabaseClients);
  testDatabaseClients.clear();

  for (const client of clients) {
    try {
      await client.close();
    } catch (err) {
      logger.debug(`Error closing test database client: ${err}`);
    }
  }
}

/**
 * Escape a SQL identifier by wrapping it in double-quotes and doubling any
 * embedded double-quote characters, e.g. `table"name` -> `"table""name"`.
 */
function escapeIdentifier(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

const DROP_KEYWORD_BY_TYPE: Record<string, string> = {
  table: 'TABLE',
  view: 'VIEW',
  trigger: 'TRIGGER',
};

/**
 * Reset the schema of a database client by dropping all user-created tables,
 * views, and triggers (but not indexes). The final statement executed is always
 * exactly `PRAGMA foreign_keys = ON`, even if a drop fails partway through.
 */
export async function resetTestDatabaseClient(client: TestDatabaseClient): Promise<void> {
  try {
    const result = await client.execute(
      "SELECT type, name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'",
    );
    const rows: SchemaObjectRow[] = result?.rows ?? [];

    for (const { type, name } of rows) {
      const keyword = DROP_KEYWORD_BY_TYPE[type];
      // Skip indexes (and anything that is not a table/view/trigger); dropping
      // the tables that own them removes them automatically.
      if (!keyword) {
